import React, { useId } from "react";

// Matching text layers preserve kerning; unpowered glass never receives bloom.
function Tubes({ className, powered }) {
  return (
    <text className={className} x="280" y="184" textAnchor="middle">
      {Array.from("curiosity.", (letter, index) => (
        <tspan key={index} className={powered && !powered.includes(index) ? "coffee-neon-unlit" : undefined}>{letter}</tspan>
      ))}
    </text>
  );
}

