import React, { useCallback, useState } from "react";
import { Link, graphql } from "gatsby";
import { Rss } from "lucide-react";
import GitHubMark from "../components/githubMark";
import HeroDesk from "../components/heroDesk";
import CoffeeInterlude from "../components/coffeeInterlude";
import Layout from "../components/layout/layout";
import PostCard from "../components/postCard";
import Category from "../components/category";
import TerminalButtonLabel from "../components/terminalButtonLabel";
import { SEO as Seo } from "../components/seo";
export default function Home({ data }) {
  const [coffee, setCoffee] = useState(null);
  const [introPhase, setIntroPhase] = useState("terminal");
  const finishIntro = useCallback(() => setIntroPhase("ready"), []);

  return (
    <Layout>
      <section className="hero enter" data-intro-phase={introPhase} data-coffee-phase={coffee?.phase || "idle"}>
        <div className="hero-copy" data-coffee-phase={coffee?.phase || "idle"}>
          <h1 className="hero-title">
            <span className="hero-title-copy">Code, circuits,<br />
              <em>and a bit of <span className="hero-last-word">curiosity.</span></em>
            </span>
          </h1>
          <div className="hero-actions">
            <Link className="button" to="/blog/">
              <TerminalButtonLabel label="Explore articles" cursor cursorActive={introPhase === "ready"} />
            </Link>
            <a className="button secondary" href="https://github.com/AhmadRoshanfar">
              <GitHubMark size={18} aria-hidden="true" focusable="false" />
              <TerminalButtonLabel label="Github" prompt={false} />
            </a>
          </div>
          {coffee?.covered && <CoffeeInterlude phase={coffee.phase} />}
        </div>
        <HeroDesk onComplete={finishIntro} onCoffeeChange={setCoffee} />
      </section>
      <section id="latest" className="latest-section" aria-labelledby="latest-title">
        <div className="section-heading">
          <h2 id="latest-title">Latest articles</h2>
          <span className="count-badge">
            {data.allMdx.totalCount}
            <span className="sr-only"> articles</span>
          </span>
        </div>
        <Category limit={5} />
        <PostCard nodes={data.allMdx.nodes} headingLevel="h3" />
        <div className="latest-actions">
          <Link className="button" to="/blog/">
            <TerminalButtonLabel label="View all articles" cursor cursorActive={introPhase === "ready"} />
          </Link>
        </div>
      </section>
      <section className="rss-callout">
        <div>
          <h2>Good things take a little tinkering.</h2>
          <p>Follow along. New notes, straight to your feed reader.</p>
        </div>
        <a className="button secondary" href="/rss.xml">
          <Rss size={17} aria-hidden="true" /> <TerminalButtonLabel label="Subscribe via RSS" prompt={false} />
        </a>
      </section>
    </Layout>
  );
}
export const query = graphql`
  query HomeArticles {
    allMdx(sort: { frontmatter: { date: DESC } }, limit: 6) {
      totalCount
      nodes {
        ...PostCardData
      }
    }
  }
`;
export const Head = () => (
  <Seo title="Ahmad Roshanfar — Firmware & Embedded Systems" description="Embedded systems and software, from C/C++ firmware and embedded Linux to applications and interfaces. Practical builds and engineering notes by Ahmad Roshanfar." />
);
