import React from "react";
import { Link, graphql, useStaticQuery } from "gatsby";
import { ArrowRight } from "lucide-react";
import { tagPath } from "../lib/content.cjs";
export default function Category({ limit, allLabel = "All articles" }) {
  const { allMdx } = useStaticQuery(graphql`
    query TopicNavigation {
      allMdx {
        group(field: { frontmatter: { tags: SELECT } }) {
          fieldValue
          totalCount
        }
      }
    }
  `);
  const tags = limit
    ? [...allMdx.group]
        .sort((a, b) => b.totalCount - a.totalCount || a.fieldValue.localeCompare(b.fieldValue))
        .slice(0, limit)
    : allMdx.group;
  return (
    <nav className="topic-nav" aria-label="Browse by topic">
      <Link className="topic-chip" to="/blog/" activeClassName="selected">
        {allLabel}
      </Link>
      {tags.map((tag) => (
        <Link
          className="topic-chip"
          activeClassName="selected"
          key={tag.fieldValue}
          to={tagPath(tag.fieldValue)}
        >
          {tag.fieldValue}
          <span>
            {tag.totalCount}
            <span className="sr-only"> {tag.totalCount === 1 ? "article" : "articles"}</span>
          </span>
        </Link>
      ))}
      {limit && (
        <Link className="topic-chip topic-chip-more" to="/tags/">
          All topics <ArrowRight size={13} aria-hidden="true" />
        </Link>
      )}
    </nav>
  );
}
