import React, { useCallback, useEffect, useRef, useState } from "react";
import { claimGreeting } from "./heroDesk/activity";

const GREETING = "Welcome to BrightBytes!";
const INTRO = "Hi there! I'm Ahmad.";
// Where the speech bubble points in the static greeting image.
const STILL_ANCHOR = { x: 0.694, y: 0.141 };

export default function HeroDesk({ enabled = true, onComplete, onCoffeeChange }) {
  const container = useRef(null);
  const canvas = useRef(null);
  const desk = useRef(null);
  const workStarted = useRef(false);
  const completed = useRef(false);
  const [mode, setMode] = useState("still");
  const [anchor, setAnchor] = useState(STILL_ANCHOR);
  const [greeting, setGreeting] = useState(false);
  const [coffee, setCoffee] = useState(null);
  const [greetingMessage, setGreetingMessage] = useState(GREETING);

  const finish = useCallback(() => {
    if (completed.current) return;
    completed.current = true;
    onComplete?.();
  }, [onComplete]);
  const handlers = useRef({});
  handlers.current = {
    greet(point, message) {
      if (point) setAnchor(point);
      if (message) setGreetingMessage(message);
      setGreeting(Boolean(point));
    },
    coffee(story) {
      setCoffee(story);
      onCoffeeChange?.(story);
      window.dispatchEvent(new CustomEvent("bb:coffee-attention", { detail: Boolean(story?.attention) }));
    },
    finish,
  };

  // Load three.js only once the hero is on screen and motion is welcome.
  useEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setMode("static");
      return undefined;
    }
    let disposed = false;
    const observer = new IntersectionObserver(([entry]) => {
      if (!entry.isIntersecting) return;
      observer.disconnect();
      import("./heroDesk/scene")
        .then(async ({ createHeroDesk }) => {
          if (disposed) return;
          const surface = container.current.closest(".site-shell") || container.current.closest(".hero");
          const scene = await createHeroDesk(canvas.current, {
            theme: document.documentElement.dataset.theme,
            onCoffee: (story) => handlers.current.coffee(story),
            onGreeting: (point, message) => handlers.current.greet(point, message),
            onActivity: (activity) => container.current?.setAttribute("data-activity", activity),
            onLighting: ({ level, power, faultA, faultB }) => {
              if (!surface) return;
              surface.style.setProperty("--neon-level", level.toFixed(3));
              surface.style.setProperty("--neon-power", power.toFixed(3));
              surface.style.setProperty("--neon-fault-a", faultA);
              surface.style.setProperty("--neon-fault-b", faultB);
            },
          });
          if (disposed) { scene.dispose(); return; }
          const { width, height } = container.current.getBoundingClientRect();
          scene.resize(width, height);
          scene.render();
          desk.current = scene;
          setMode("live");
        })
        .catch(() => {
          // WebGL or the chunk is unavailable; the illustration stays readable.
          if (!disposed) setMode("static");
        });
    });
    observer.observe(container.current);
    return () => {
      disposed = true;
      observer.disconnect();
      desk.current?.dispose();
      desk.current = null;
    };
  }, []);

  // Pause off screen, in hidden tabs, or when reduced motion is turned on.
  useEffect(() => {
    if (mode !== "live") return undefined;
    const scene = desk.current;
    const motion = window.matchMedia("(prefers-reduced-motion: reduce)");
    let visible = true;
    const sync = () => {
      if (visible && !document.hidden && !motion.matches) scene.start();
      else {
        scene.stop();
        if (!visible || motion.matches) {
          scene.cancelStory();
          setGreeting(false);
          scene.setTheme(document.documentElement.dataset.theme);
          scene.render();
        }
      }
    };
    const observer = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      sync();
    });
    const resize = new ResizeObserver(([entry]) => {
      scene.resize(entry.contentRect.width, entry.contentRect.height);
      scene.render();
    });
    const theme = new MutationObserver(() => {
      scene.setTheme(document.documentElement.dataset.theme, true);
      scene.render();
    });
    observer.observe(container.current);
    resize.observe(container.current);
    theme.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
    const support = () => scene.support();
    const supportHover = (event) => scene.supportHover(Boolean(event.detail));
    window.addEventListener("bb:support-hover", supportHover);
    window.addEventListener("bb:support-activate", support);
    document.addEventListener("visibilitychange", sync);
    motion.addEventListener("change", sync);
    sync();
    return () => {
      observer.disconnect();
      resize.disconnect();
      theme.disconnect();
      window.removeEventListener("bb:support-hover", supportHover);
      window.removeEventListener("bb:support-activate", support);
      document.removeEventListener("visibilitychange", sync);
      motion.removeEventListener("change", sync);
      scene.stop();
    };
  }, [mode]);

  useEffect(() => {
    if (!enabled) return undefined;
    if (mode === "live" && !workStarted.current) {
      workStarted.current = true;
      desk.current.beginWork();
    }
    if (mode === "static" && !workStarted.current) {
      workStarted.current = true;
      if (claimGreeting()) { setAnchor(STILL_ANCHOR); setGreetingMessage(INTRO); setGreeting(true); }
    }
    if (mode === "live" || mode === "static") {
      finish();
      return undefined;
    }
    const timer = window.setTimeout(finish, 2500);
    return () => window.clearTimeout(timer);
  }, [enabled, mode, finish]);

  useEffect(() => {
    if (!greeting || mode === "live") return undefined;
    const intro = window.setTimeout(() => setGreetingMessage(GREETING), 1700);
    const end = window.setTimeout(() => setGreeting(false), 3800);
    return () => { window.clearTimeout(intro); window.clearTimeout(end); };
  }, [greeting, mode]);

  const bubble = coffee?.message ? coffee.anchor : mode === "live" ? anchor : STILL_ANCHOR;
  return (
    <div
      ref={container}
      className="hero-desk"
      data-mode={mode}
      data-greeting={greeting}
      data-coffee={coffee?.phase || "idle"}
      role="img"
      aria-label="Ahmad at his workbench. He introduces himself once when the scene loads, then reads a schematic, solders a board, writes firmware, then carries the board over to check it with a multimeter and oscilloscope."
    >
      <div className="hero-desk-still" />
      <canvas ref={canvas} className="hero-desk-canvas" aria-hidden="true" />
      <span
        className="hero-desk-bubble"
        aria-hidden="true"
        data-visible={Boolean(greeting || coffee?.message)}
        style={{ "--bubble-x": bubble.x, "--bubble-y": bubble.y }}
      >
        {coffee?.message || greetingMessage}
      </span>
      <span className="hero-desk-doze" aria-hidden="true" data-visible={coffee?.phase === "sleep" || coffee?.phase === "neon"} style={{ "--bubble-x": coffee?.anchor.x || STILL_ANCHOR.x, "--bubble-y": coffee?.anchor.y || STILL_ANCHOR.y }}>z<span>z</span><span>Z</span></span>
    </div>
  );
}
